/** @type {import('next').NextConfig} */
const nextConfig = {
  typescript: {
    ignoreBuildErrors: true,
  },
  images: {
    unoptimized: true,
  },
  /**
   * Serve the Pharma Portal mark at the classic /favicon.ico path.
   *
   * The app icon is generated by app/icon.tsx, which Next serves at `/icon` — but
   * browsers, crawlers and platform dashboards (Vercel's project switcher among
   * them) still request `/favicon.ico` first. That path 404'd, so those consumers
   * fell back to the icon they had cached from the old v0 build, which is why the
   * Pharma Portal project kept wearing the v0 logo while sibling projects showed
   * their real favicon. Alias the convention to the real mark.
   */
  async rewrites() {
    return {
      beforeFiles: [{ source: '/favicon.ico', destination: '/icon' }],
    }
  },
}

export default nextConfig
